// Table-driven Turing machine for {0^n 1^n | n >= 0}
// Strategy: mark the leftmost 0 as X, then the leftmost unmarked 1 as Y,
// walk back to the X, repeat. When no 0 is left, only Y's may remain.

const BLANK = '_';
// delta[state][symbol] = [nextState, symbolToWrite, move]
const delta = {
  q0: { '0': ['q1', 'X', 'R'], 'Y': ['q3', 'Y', 'R'], [BLANK]: ['accept', BLANK, 'R'] },
  q1: { '0': ['q1', '0', 'R'], 'Y': ['q1', 'Y', 'R'], '1': ['q2', 'Y', 'L'] },
  q2: { '0': ['q2', '0', 'L'], 'Y': ['q2', 'Y', 'L'], 'X': ['q0', 'X', 'R'] },
  q3: { 'Y': ['q3', 'Y', 'R'], [BLANK]: ['accept', BLANK, 'R'] },
};
// Any (state, symbol) pair missing from the table means: halt and REJECT.

function runTM(input, maxSteps = 10_000) {
  const tape = new Map([...input].map((ch, i) => [i, ch])); // unbounded tape
  let head = 0, state = 'q0';
  for (let step = 0; step < maxSteps; step++) {
    if (state === 'accept') return 'ACCEPT';
    const sym = tape.get(head) ?? BLANK;
    const rule = delta[state][sym];
    if (!rule) return 'REJECT';
    const [next, write, move] = rule;
    tape.set(head, write);
    head += move === 'R' ? 1 : -1;
    state = next;
  }
  return 'NO ANSWER YET (step limit hit)'; // a real TM might still halt later
}

for (const w of ['', '01', '0011', '001', '0111', '10', '0101']) {
  console.log(JSON.stringify(w).padEnd(7), runTM(w));
}
