// The halting problem: why no general solver can exist.
// We CANNOT write a real halts() — but we can show the contradiction.

// Hypothetical decider (impossible to implement for all programs):
// function halts(program, input) { /* ...magic: returns true or false... */ }

// The diagonal program D:
// function diagonal(program) {
//   if (halts(program, program)) { while (true) {} } // H says "halts" → loop
//   else { return 'done'; }                          // H says "loops" → halt
// }
// diagonal(diagonal):
//   if it halts, halts() said true → it loops. Contradiction.
//   if it loops, halts() said false → it returns. Contradiction.
// So halts() cannot exist.

// ── What we CAN do: run a program for a bounded number of steps ──
// Model a "program" as a generator: each yield is one step of work.
function runWithBudget(program, maxSteps) {
  const it = program();
  for (let step = 0; step < maxSteps; step++) {
    const { done, value } = it.next();
    if (done) return { halted: true, steps: step, value };
  }
  return { halted: 'unknown', steps: maxSteps }; // NOT the same as "loops forever"
}

function* countTo(n) { for (let i = 0; i < n; i++) yield i; return 'done'; }
function* forever() { while (true) yield; }
function* collatz(n) {            // nobody has proved this halts for every n
  while (n !== 1) { n = n % 2 ? 3 * n + 1 : n / 2; yield n; }
  return 'reached 1';
}

console.log(runWithBudget(() => countTo(10), 1000));    // { halted: true, steps: 10, value: 'done' }
console.log(runWithBudget(() => collatz(27), 1000));    // { halted: true, steps: 111, value: 'reached 1' }
console.log(runWithBudget(forever, 1000));              // { halted: 'unknown', steps: 1000 }
console.log(runWithBudget(() => countTo(5000), 1000));  // { halted: 'unknown', ... } — but it WOULD halt
// A "yes" answer is trustworthy; "unknown" never turns into a safe "no".
// That one-sidedness is exactly what makes HALT recognisable but not decidable.

// Rice's theorem in practice: every automatic program checker gives something up.
// Property: "does this function ever return 42?" — semantic and non-trivial,
// so no algorithm decides it for ALL programs.
//
// A checker can have at most two of these three:
//   1. SOUND      — never misses a real problem (no false negatives)
//   2. COMPLETE   — never raises a false alarm (no false positives)
//   3. AUTOMATIC  — needs no human help and always terminates

const tools = [
  { name: 'Rust borrow checker / OCaml types',
    givesUp: 'completeness: rejects some safe programs (hence unsafe blocks and RefCell)' },
  { name: 'TypeScript',
    givesUp: 'soundness, deliberately: any, as, bivariant methods, unchecked indexing' },
  { name: 'ESLint rules',
    givesUp: 'both: heuristic pattern checks, some false alarms, many misses' },
  { name: 'Tests, Valgrind, sanitizers',
    givesUp: 'soundness: only executed paths are checked (but every report is real)' },
  { name: 'Rocq / Lean / Dafny proofs',
    givesUp: 'automation: a human supplies specs, invariants, and proofs' },
];

for (const t of tools) console.log(`${t.name} → gives up ${t.givesUp}`);
console.log('\nRice: a perfect, fully automatic analyser of program behaviour cannot exist.');
